/// <summary>
/// PaffH 29.04.22
/// </summary>
/// <param name = "_batchJobId">RecId</param>
/// <returns>NDXBatchJobPALabelSaved2NDXDatabase</returns>
static NDXBatchJobPALabelSaved2NDXDatabase construct(RecId _batchJobId = 0)
{
    NDXBatchJobPALabelSaved2NDXDatabase nDXBatchJobPALabelSaved2NDXDatabase = new NDXBatchJobPALabelSaved2NDXDatabase(_batchJobId);
    BatchHeader batchHeader = nDXBatchJobPALabelSaved2NDXDatabase.parmBatchHeader();
    if (batchHeader.parmBatchGroup() != batchGroupId)
    {
        batchHeader.parmBatchGroup(nDXBatchJobPALabelSaved2NDXDatabase.parmBatchGroup(batchGroupId, batchGroupIdDescription).Group);
    }
    return nDXBatchJobPALabelSaved2NDXDatabase;
}

/// <summary>
/// PaffH 29.04.22
/// </summary>
/// <param name = "_args">Args</param>
/// <returns>RefRecId</returns>
public RefRecId addTask(Args _args = new Args())
{

    NDXPALabelSaved2NDXDatabaseController controller = NDXPALabelSaved2NDXDatabaseController::construct(_args);

    NDXPALabelSaved2NDXDatabaseContract contract = controller.getDataContractObject('_contract');
    if (!contract)
    {
        // Function %1 was called with an invalid value
        throw Error(strFmt("@SYS23264", classStr(NDXPALabelSaved2NDXDatabaseContract)));
    }

    SysRecurrenceData sysRecurrenceData = SysRecurrence::defaultRecurrence();
    sysRecurrenceData = SysRecurrence::setRecurrenceStartDateTime(sysRecurrenceData, DateTimeUtil::addHours(DateTimeUtil::utcNow(), 1));
    sysRecurrenceData = SysRecurrence::setRecurrenceNoEnd(sysRecurrenceData);
    sysRecurrenceData = SysRecurrence::setRecurrenceUnit(sysRecurrenceData, SysRecurrenceUnit::Minute, 10);
    batchHeader.parmRecurrenceData(sysRecurrenceData);

    batchHeader.parmCaption("@NDX:NDXClassDescriptionNDXBatchJobPALabelSaved2NDXDatabase");
    batchHeader.parmStartDateTime(DateTimeUtil::addHours(DateTimeUtil::utcNow(), 1));    // job shouldn't start immediately
    batchHeader.parmLogLevel(BatchLogLevel::Always);
    batchHeader.parmExecutingBy(#AdminUser);

    controller.parmDialogCaption(batchHeader.parmCaption());
    batchHeader.addTask(controller);
    batchHeader.save();

    return batchHeader.parmBatchHeaderId();
}

/// <summary>
/// PaffH 11.05.22
/// </summary>
/// <returns>ClassDescription</returns>
client server static ClassDescription description()
{
    return "@NDX:NDXClassDescriptionNDXBatchJobPALabelSaved2NDXDatabase";
}
